const YANDEX_REVIEWS_LINK="https://yandex.ru/maps/org/nisspro/160414818619/reviews/?ll=50.152565%2C53.199417&z=16",reviewsData=[{name:"Александр Л.",avatarLetter:"А",rating:5,text:"О сервисе узнал от знакомого, который его рекомендовал. Приехал ко времени, предварительно созвонился и обговорили дату и время. Сразу загнали и приступили к работе. Вес персонал вежливый, обходительный, есть комната для клиентов, где удобные кресла и телевизор",source:"Яндекс Карты"},{name:"Дмитрий Рогачев",avatarLetter:"Д",rating:5,text:"Отменный сервис. Чинился и на х трейле 6 лет назад. И сейчас Патфайндер гибрид обслуживаю уже на протяжении 5.5 лет! Один раз поменял масло у других, пожалел. Сегодня в очередной раз убедился, если у тебя ниссан то лучше всего обслуживаться именно здесь!!! Спасибо ребят✊",source:"Яндекс Карты"},{name:"Андрей Бледных",avatarLetter:"А",rating:4,text:"Обращался по поводу диагностики Nissan Qashqai, машина периодически отказывалась заводиться без видимых причин. Диагност быстро нашел неисправность в стартере, сразу всё устранили, не навязывая не нужных работ. Также сделали осмотр ходовой и подкапотного пространства, выдали рекомендации. По запчастям предлагают как оригинал, так и более доступные аналоги. В итоге впечатление о работе сервиса отличное, буду обращаться еще",source:"Яндекс Карты"},{name:"RIXSO",avatarLetter:"R",rating:5,text:"Приезжал на авто Nissan Almera G15, с проблемой обрыва обогревателя водительского сиденья. Мастер сразу же обнаружил причину поломки и оперативно устранил ее. В сервисе чисто, руководитель приятно лоялен к клиентам. В данный момент работаем над следующим ремонтом в авто.",source:"Яндекс Карты"},{name:"Алексей М.",avatarLetter:"A",rating:5,text:"Отличный авто сервис!Обслуживаюсь много лет в этом сервисе.Очень клиентоориентированный персонал.Делают всегда качественно и в срок.Приятная зона ожидания.Приемлемый ценник.Запчасти тоже у них можно приобрести.Советую!",source:"Яндекс Карты"},{name:"Сергей Бекеев",avatarLetter:"C",rating:5,text:"Сервис хороший сотрудники отличные вчера ездил менять подшипник ступицы задний на nissan qashqai всё поменяли быстро и качественно рекомендую",source:"Яндекс Карты"}];function renderRating(e){let a="";for(let t=1;t<=5;t++)t<=e?a+='<span class="star">★</span>':a+='<span class="star empty">★</span>';return a}function escapeHtml(e){return e?e.replace(/[&<>]/g,function(e){return"&"===e?"&amp;":"<"===e?"&lt;":">"===e?"&gt;":e}):""}const track=document.getElementById("reviewsTrack");function buildReviews(){track.innerHTML="",reviewsData.forEach(e=>{let a=document.createElement("div");a.className="review-card",a.innerHTML=`
            <div class="review-header">
                <div class="avatar">${escapeHtml(e.avatarLetter)}</div>
                <div class="reviewer-info">
                    <div class="reviewer-name">${escapeHtml(e.name)}</div>
                    <div class="review-date">${escapeHtml(e.date)}</div>
                </div>
            </div>
            <div class="rating">
                ${renderRating(e.rating)}
            </div>
            <div class="review-text">
                ${escapeHtml(e.text)}
            </div>
            <div class="review-source">
                <span class="source-icon">📌 Яндекс</span>
                <span>${escapeHtml(e.source)}</span>
            </div>
        `,track.appendChild(a)});let e=document.createElement("a");e.className="review-card-all",e.href="https://yandex.ru/maps/org/nisspro/160414818619/reviews/?ll=50.152565%2C53.199417&z=16",e.target="_blank",e.rel="noopener noreferrer",e.innerHTML=`
        <div class="all-reviews-icon">⭐</div>
        <div class="all-reviews-title">Все отзывы</div>
        <div class="all-reviews-text">
            Читайте все отзывы<br>
            о нашей работе на Яндекс Картах
        </div>
        <div class="all-reviews-button">Смотреть →</div>
    `,track.appendChild(e)}const carousel=document.getElementById("reviewsCarousel"),scrollLeftBtn=document.getElementById("scrollLeftBtn"),scrollRightBtn=document.getElementById("scrollRightBtn");function scrollCarousel(e){"left"===e?carousel.scrollBy({left:-360,behavior:"smooth"}):carousel.scrollBy({left:360,behavior:"smooth"})}scrollLeftBtn.addEventListener("click",()=>scrollCarousel("left")),scrollRightBtn.addEventListener("click",()=>scrollCarousel("right")),buildReviews();